"""调用工具自身的清理能力，保留最新构建和仍被引用的依赖。"""
import os
from pathlib import Path
import shutil
import subprocess
import sys
from cleanup_files import cache_target, display_path
from cleanup_rules import browser_cache_rules, incremental_rules


def processes_running(names):
    """Fail closed if the process list cannot be checked."""
    command = ["tasklist", "/FO", "CSV", "/NH"] if sys.platform == "win32" else ["ps", "-A", "-o", "comm="]
    output = subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    for line in output.stdout.splitlines():
        name = line.split('\",\"', 1)[0].strip('"') if sys.platform == "win32" else Path(line.strip()).name
        if name.casefold() in names:
            return True
    return False


def run_tool(label, command, dry_run, preview_supported=True, cwd=None, env=None):
    if dry_run and not preview_supported:
        print(f"[{label}] 仅预览：工具不支持无副作用预览，本次不执行。")
        return label, "未执行（工具不支持预览）"
    executable = shutil.which(command[0])
    if not executable:
        print(f"[{label}] 未安装 {command[0]}，已跳过。")
        return label, "未执行（工具未安装）"
    print(f"[{label}] {'开始预览' if dry_run else '开始清理'}，以下为工具原始输出：", flush=True)
    # Argument arrays only: no shell, installation, sudo or force flags.
    result = subprocess.run([executable, *command[1:]], cwd=cwd, env=env, check=False)
    return label, ("预览完成" if dry_run else "清理完成") if result.returncode == 0 else "执行失败"


def optional_cleanup(args, apply_rules):
    tools = []

    def step(label, action):
        try:
            action()
        except (OSError, ValueError, subprocess.SubprocessError) as error:
            tools.append((label, "执行失败"))
            print(f"[{label}] 执行失败：", str(error).replace(str(Path.home()), "~"))

    def browsers():
        if not args.dry_run and processes_running({"google chrome", "microsoft edge", "chrome", "chrome.exe", "msedge", "msedge.exe"}):
            tools.append(("浏览器缓存", "未执行（请先完全退出 Chrome 和 Edge）"))
        else:
            apply_rules(browser_cache_rules(days=args.browser_days))

    def builds():
        if not args.dry_run and processes_running({"cargo", "cargo.exe", "rustc", "rustc.exe"}):
            tools.append(("Rust 构建缓存", "未执行（检测到编译进程）"))
        else:
            for target in args.rust_targets:
                step("Rust 增量缓存 " + display_path(Path(target).expanduser()), lambda: apply_rules(incremental_rules(target, args.incremental_days)))
            for project in args.agent_hub_projects:
                step("AgentHub 历史构建", lambda: project_builds(project))

    def project_builds(directory):
        project = Path(directory).expanduser().absolute()
        scripts = cache_target(project, "scripts")
        script = scripts / "app/build.mjs"
        if not script.is_file():
            script = scripts / "build.mjs"
        if not script.is_file() or not (project / "src-tauri/Cargo.toml").is_file():
            raise ValueError("请指定可信任的 AgentHub 源码目录，其中须包含 scripts/app/build.mjs 和 src-tauri/Cargo.toml。")
        target = cache_target(project / "src-tauri", "target")
        command = ["node", str(script), "prune"] + (["--dry-run"] if args.dry_run else [])
        env = dict(os.environ, CARGO_TARGET_DIR=str(target))
        tools.append(run_tool("AgentHub 历史构建 " + display_path(project), command, args.dry_run, cwd=project, env=env))

    def brew():
        env = dict(os.environ, HOMEBREW_NO_AUTO_UPDATE="1", HOMEBREW_NO_ANALYTICS="1")
        command = ["brew", "cleanup", "--prune=" + str(args.download_days)] + (["--dry-run"] if args.dry_run else [])
        tools.append(run_tool("Homebrew 历史下载与版本", command, args.dry_run, env=env))

    if args.detect_workspace_builds:
        workspace = Path.cwd()
        if (workspace / "src-tauri/Cargo.toml").is_file() and any((workspace / path).is_file() for path in ("scripts/app/build.mjs", "scripts/build.mjs")):
            args.agent_hub_projects = list(dict.fromkeys([*args.agent_hub_projects, str(workspace)]))
        elif (workspace / "Cargo.toml").is_file():
            args.rust_targets = list(dict.fromkeys([*args.rust_targets, str(workspace / "target")]))

    if args.browser_cache:
        step("浏览器缓存", browsers)
    if args.rust_targets or args.agent_hub_projects:
        step("Rust 构建缓存", builds)
    if args.uv_prune:
        step("uv 无引用缓存", lambda: tools.append(run_tool("uv 无引用缓存", ["uv", "cache", "prune", "--offline", "--no-python-downloads"], args.dry_run, preview_supported=False)))
    if args.brew_cleanup:
        step("Homebrew 历史下载与版本", brew)
    if args.updater_cache:
        def updates():
            rules, notices = updater_rules(args.updater_days)
            tools.extend(notices)
            apply_rules(rules)
        step("应用旧更新缓存", updates)
    return tools


def numeric_version(value):
    import re
    if not isinstance(value, str) or not re.fullmatch(r"\d+(?:\.\d+)*", value):
        return None
    parts = tuple(int(part) for part in value.split("."))
    while len(parts) > 1 and parts[-1] == 0:
        parts = parts[:-1]
    return parts


def installed_app_info(app_name):
    import plistlib
    for parent in (Path("/Applications"), Path.home() / "Applications"):
        info = parent / app_name / "Contents/Info.plist"
        if info.is_file():
            return plistlib.loads(info.read_bytes())
    return None


def updater_rules(days):
    """只清理已安装同等或更新版本的旧 macOS 包；pending 和未知格式一律保留。"""
    import plistlib
    import time
    if sys.platform != "darwin":
        return [], [("应用更新缓存", "未执行（当前平台无可验证的更新缓存规则）")]
    if processes_running({"shipit", "autoupdate"}):
        return [], [("应用更新缓存", "未执行（检测到更新进程）")]
    home = Path.home()
    caches = home / "Library/Caches"
    specifications = [
        ("Visual Studio Code.app", caches, "com.microsoft.VSCode.ShipIt", "update."),
        ("Codex.app", caches / "com.openai.codex/org.sparkle-project.Sparkle", "Installation", ""),
    ]
    rules, notices = [], []
    for app_name, parent, child, prefix in specifications:
        base = cache_target(parent, child)
        if not base.is_dir():
            continue
        installed_info = installed_app_info(app_name)
        if installed_info is None:
            notices.append((app_name + " 更新缓存", "未执行（无法确认已安装版本）"))
            continue
        for candidate in base.iterdir():
            if not candidate.name.startswith(prefix) or not candidate.is_dir() or candidate.is_symlink():
                continue
            package = cache_target(base, candidate.name)
            info_path = cache_target(package, app_name + "/Contents/Info.plist")
            if not info_path.is_file():
                continue
            info = plistlib.loads(info_path.read_bytes())
            if not info.get("CFBundleIdentifier") or info.get("CFBundleIdentifier") != installed_info.get("CFBundleIdentifier"):
                notices.append((app_name + " 更新缓存", "未执行（应用标识不匹配）"))
                continue
            keys = ("CFBundleVersion", "CFBundleShortVersionString")
            versions = next(((numeric_version(info.get(key)), numeric_version(installed_info.get(key))) for key in keys if numeric_version(info.get(key)) is not None and numeric_version(installed_info.get(key)) is not None), None)
            if versions is None or versions[0] > versions[1]:
                notices.append((app_name + " 更新缓存", "未执行（新版本待安装或版本无法比较）"))
                continue
            metadata = package.lstat()
            if max(metadata.st_mtime, getattr(metadata, "st_birthtime", 0)) >= time.time() - days * 86400:
                notices.append((app_name + " 更新缓存", "未执行（仍在保留期内）"))
                continue
            rules.append((app_name + " 已安装旧更新包", base, package.name, days, False))
    return rules, notices

"""读取独立 JSON 配置并应用 CLI 覆盖；校验完成前不执行清理。"""
import argparse
import json
from pathlib import Path
from types import SimpleNamespace
from cleanup_files import cache_target

DAY_KEYS = {"workspace_tmp_days", "workspace_log_days", "download_days", "agent_days", "browser_days", "incremental_days", "updater_days"}
BOOL_KEYS = {"user_caches", "agent_caches", "browser_cache", "uv_prune", "brew_cleanup", "updater_cache", "notify", "detect_workspace_builds"}
LIST_KEYS = {"agent_hub_projects", "rust_targets", "extra_cache_rules"}


def load_config(path):
    path = Path(path)
    if path.is_symlink():
        raise ValueError("配置文件不能是符号链接。")
    content = path.read_text(encoding="utf-8-sig")
    # AgentHub 给每个已安装模板文件加归属标记；配置正文仍为标准 JSON。
    if content.startswith("# AgentHub automation script: agent_hub:"):
        content = content.partition("\n")[2]
    data = json.loads(content)
    if not isinstance(data, dict) or set(data) != DAY_KEYS | BOOL_KEYS | LIST_KEYS:
        raise ValueError("配置字段缺失或不受支持，请对照预装 cleanup-config.json。")
    for key in DAY_KEYS:
        if type(data[key]) is not int or data[key] < 1:
            raise ValueError(key + " 必须为正整数。")
    for key in BOOL_KEYS:
        if type(data[key]) is not bool:
            raise ValueError(key + " 必须为 true 或 false。")
    for key in LIST_KEYS:
        if not isinstance(data[key], list):
            raise ValueError(key + " 必须为数组。")
    for key in ("agent_hub_projects", "rust_targets"):
        if any(not isinstance(value, str) or not value.strip() for value in data[key]):
            raise ValueError(key + " 只能包含非空目录路径。")
        for value in data[key]:
            cache_target(Path(value).expanduser(), ".cleanup-boundary-check")
    for rule in data["extra_cache_rules"]:
        if not isinstance(rule, list) or len(rule) != 4 or not all(isinstance(v, str) and v for v in rule[:3]) or type(rule[3]) is not int or rule[3] < 1:
            raise ValueError("extra_cache_rules 每项为 [名称, 根目录, 子目录, 正整数保留天数]。")
        cache_target(rule[1], rule[2])
    return data


def parse_options(default_config):
    parser = argparse.ArgumentParser(description="自动清理过期缓存和历史构建，保留对话、凭据、运行时和被引用的依赖，输出中文总结及桌面通知。")
    parser.add_argument("--config", type=Path, default=default_config, help="配置文件路径，默认使用任务 config/cleanup-config.json，兼容旧入口旁的配置")
    parser.add_argument("--dry-run", action="store_true", help="只预览，不删除文件，不发通知；无预览能力的工具不执行")
    parser.add_argument("--workspace-only", action="store_true", help="仅清理工作目录 tmp/logs，默认不发通知")
    parser.add_argument("--no-tools", action="store_true", help="跳过构建、uv、Homebrew 和更新缓存清理")
    for key, name, help_text in [
        ("browser_cache", "browser-cache", "浏览器网页与代码缓存"),
        ("uv_prune", "uv-prune", "uv 无引用缓存"),
        ("brew_cleanup", "brew-cleanup", "Homebrew 历史版本与下载"),
        ("updater_cache", "updater-cache", "确认已安装版本后的旧更新缓存"),
        ("notify", "notify", "完成后发送桌面通知"),
    ]:
        group = parser.add_mutually_exclusive_group()
        group.add_argument("--" + name, dest=key, action="store_true", default=None, help="启用" + help_text)
        group.add_argument("--skip-" + name, dest=key, action="store_false", help="跳过" + help_text)
    parser.add_argument("--skip-agent-cache", action="store_true", help="跳过 Agent 缓存、Shell 快照和诊断日志")
    parser.add_argument("--agent-cache-days", dest="agent_days", type=int, help="Agent 缓存及日志保留天数，默认由配置决定")
    parser.add_argument("--download-cache-days", dest="download_days", type=int, help="下载缓存保留天数")
    parser.add_argument("--rust-target", action="append", default=[], metavar="目录", help="追加 Cargo target，只清理过期 incremental，不清 deps 或最终程序")
    parser.add_argument("--agent-hub-project", action="append", default=[], metavar="源码目录", help="追加可信任的 AgentHub 源码目录，调用其工具保留最新构建")
    cli = parser.parse_args()
    try:
        data = load_config(cli.config)
        for key in ("browser_cache", "uv_prune", "brew_cleanup", "updater_cache", "notify", "agent_days", "download_days"):
            value = getattr(cli, key)
            if value is not None:
                if key in DAY_KEYS and value < 1:
                    raise ValueError(key + " 必须为正整数。")
                data[key] = value
        data["agent_caches"] &= not cli.skip_agent_cache
        data["rust_targets"] = list(dict.fromkeys(data["rust_targets"] + cli.rust_target))
        data["agent_hub_projects"] = list(dict.fromkeys(data["agent_hub_projects"] + cli.agent_hub_project))
        if cli.workspace_only:
            if any(getattr(cli, key) is True for key in ("browser_cache", "uv_prune", "brew_cleanup", "updater_cache")) or cli.rust_target or cli.agent_hub_project:
                raise ValueError("--workspace-only 不能与其他清理项一起启用。")
            for key in ("user_caches", "agent_caches", "browser_cache", "uv_prune", "brew_cleanup", "updater_cache", "detect_workspace_builds"):
                data[key] = False
            data["rust_targets"], data["agent_hub_projects"] = [], []
            data["notify"] = cli.notify is True
        if cli.no_tools:
            for key in ("uv_prune", "brew_cleanup", "updater_cache", "detect_workspace_builds"):
                data[key] = False
            data["rust_targets"], data["agent_hub_projects"] = [], []
        return SimpleNamespace(**data, dry_run=cli.dry_run)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        parser.error(str(error).replace(str(Path.home()), "~"))

"""文件清理与路径边界；只删除明确目录内的过期普通文件。"""
import os
from pathlib import Path
import shutil
import stat
import time


def human_bytes(value):
    sign = "-" if value < 0 else ""
    size = abs(value)
    for unit in ("B", "KiB", "MiB", "GiB", "TiB", "PiB"):
        if size < 1024 or unit == "PiB":
            return f"{sign}{size:.0f} B" if unit == "B" else f"{sign}{size:.2f} {unit}"
        size /= 1024


def display_path(path):
    try:
        return "~/" + str(Path(path).relative_to(Path.home()))
    except ValueError:
        return str(path)


def is_link(metadata):
    return stat.S_ISLNK(metadata.st_mode) or bool(
        getattr(metadata, "st_file_attributes", 0)
        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
    )


def cache_target(root, child):
    root = Path(root).expanduser()
    child = Path(child)
    if not root.is_absolute() or child.is_absolute() or not child.parts or any(
        part in (".", "..") for part in child.parts
    ):
        raise ValueError("缓存规则必须指定绝对根目录和相对子目录。")
    home = Path.home()
    try:
        relative = root.relative_to(home)
        root.resolve().relative_to(home.resolve())
    except ValueError:
        raise ValueError("缓存根目录必须位于当前用户主目录内。") from None
    if not relative.parts or ".." in relative.parts:
        raise ValueError("不能将用户主目录本身作为缓存根目录。")
    target = home
    for part in [*relative.parts, *child.parts]:
        target = target / part
        try:
            if is_link(target.lstat()):
                raise ValueError("缓存目录不能是符号链接或目录联接。")
        except FileNotFoundError:
            pass
    if target.resolve().parent == target.resolve():
        raise ValueError("不能清理文件系统根目录。")
    return target


def counters():
    return dict(scanned=0, eligible=0, candidate_bytes=0, removed=0, removed_bytes=0, skipped=0, warnings=0, errors=0)


def access_error(result, error, path, skip_permission_denied):
    if skip_permission_denied and isinstance(error, PermissionError):
        result["skipped"] += 1
        result["warnings"] += 1
        print("跳过受保护的缓存：", display_path(path), "（权限不足）")
    else:
        result["errors"] += 1
        print("清理访问失败：", display_path(path), type(error).__name__)


def entry_metadata(entry):
    metadata = entry.stat(follow_symlinks=False)
    # Windows DirEntry.stat may leave st_dev at zero.
    return Path(entry.path).lstat() if metadata.st_dev == 0 else metadata


def expired(metadata, cutoff, protect_access):
    last_use = max(metadata.st_mtime, getattr(metadata, "st_atime", 0)) if protect_access else metadata.st_mtime
    return last_use < cutoff


def clean_target(target, retention_days, dry_run=False, protect_access=False, skip_permission_denied=False, allow_hardlinks=False):
    if not isinstance(retention_days, int) or isinstance(retention_days, bool) or retention_days < 1:
        raise ValueError("保留天数必须为正整数。")
    result = counters()
    try:
        root = target.lstat()
    except FileNotFoundError:
        print("跳过不存在的目录：", display_path(target))
        return result
    except OSError as error:
        access_error(result, error, target, skip_permission_denied)
        return result
    if is_link(root) or not stat.S_ISDIR(root.st_mode):
        raise ValueError("清理目标必须是实际目录，不能是符号链接或目录联接。")
    cutoff = time.time() - retention_days * 86400
    pending = [target]
    while pending:
        parent = pending.pop()
        try:
            current = parent.lstat()
            if is_link(current) or current.st_dev != root.st_dev:
                result["skipped"] += 1
                continue
            with os.scandir(parent) as entries:
                for entry in entries:
                    try:
                        metadata = entry_metadata(entry)
                        if is_link(metadata) or metadata.st_dev != root.st_dev:
                            result["skipped"] += 1
                        elif stat.S_ISDIR(metadata.st_mode):
                            pending.append(Path(entry.path))
                        elif stat.S_ISREG(metadata.st_mode):
                            clean_file(Path(entry.path), metadata, cutoff, protect_access, dry_run, result, target, allow_hardlinks)
                    except FileNotFoundError:
                        result["skipped"] += 1
                    except OSError as error:
                        access_error(result, error, entry.path, skip_permission_denied)
        except OSError as error:
            access_error(result, error, parent, skip_permission_denied)
    return result


def clean_file(path, metadata, cutoff, protect_access, dry_run, result, boundary, allow_hardlinks=False):
    result["scanned"] += 1
    if path.name.endswith((".lock", ".pid", ".sock")) or (not allow_hardlinks and getattr(metadata, "st_nlink", 1) > 1):
        result["skipped"] += 1
        return
    if not expired(metadata, cutoff, protect_access):
        return
    # Recheck immediately before unlinking: editors/downloads may have replaced it.
    parent = path.parent
    while True:
        if is_link(parent.lstat()):
            result["skipped"] += 1
            return
        if parent == boundary:
            break
        if parent.parent == parent:
            raise ValueError("文件已超出指定清理目录。")
        parent = parent.parent
    current = path.lstat()
    if is_link(current) or not stat.S_ISREG(current.st_mode) or (not allow_hardlinks and getattr(current, "st_nlink", 1) > 1) or (
        current.st_dev, current.st_ino, current.st_size, current.st_mtime_ns
    ) != (metadata.st_dev, metadata.st_ino, metadata.st_size, metadata.st_mtime_ns) or not expired(current, cutoff, protect_access):
        result["skipped"] += 1
        return
    result["eligible"] += 1
    result["candidate_bytes"] += current.st_size
    if not dry_run:
        path.unlink()
        result["removed"] += 1
        result["removed_bytes"] += current.st_size


def report_target(label, target, days, dry_run=False, protect_access=False, skip_permission_denied=False, allow_hardlinks=False):
    result = clean_target(target, days, dry_run, protect_access, skip_permission_denied, allow_hardlinks)
    action = "预计删除" if dry_run else "已删除"
    count = result["eligible"] if dry_run else result["removed"]
    size = result["candidate_bytes"] if dry_run else result["removed_bytes"]
    print(f"[{label}] {display_path(target)} | 保留 {days} 天 | 已扫描：{result['scanned']} | {action}：{count} 个文件（{human_bytes(size)}） | 跳过：{result['skipped']} | 警告：{result['warnings']} | 错误：{result['errors']}")
    if allow_hardlinks:
        print("增量缓存仅移除目标目录中的过期链接，其他位置的内容保留；共享文件大小不等于实际释放空间。")
    return result


def cleanup_files(directory, retention_days, dry_run=False):
    if Path(directory).is_absolute() or len(Path(directory).parts) != 1 or directory in (".", ".."):
        raise ValueError("工作目录规则只能指定直接子目录名称。")
    return report_target("工作目录 " + directory, Path.cwd() / directory, retention_days, dry_run)


def disk_space(label):
    usage = shutil.disk_usage(Path.cwd())
    ratio = usage.used / usage.total * 100 if usage.total else 0
    print(f"{label} 总容量：{human_bytes(usage.total)} | 已用：{human_bytes(usage.used)} | 可用：{human_bytes(usage.free)} | 使用率：{ratio:.1f}%")
    return usage

"""预装磁盘清理入口；策略在 cleanup-config.json，模块与配置随模板一起安装。"""
from pathlib import Path
import sys
import time

# 同时支持直接执行及测试中的 runpy；仅加载本脚本同目录模块。
sys.dont_write_bytecode = True
sys.path.insert(0, str(Path(__file__).resolve().parent))
from cleanup_config import parse_options
from cleanup_files import counters, access_error, cache_target, cleanup_files, disk_space, report_target
from cleanup_rules import user_cache_rules, agent_cache_rules
from cleanup_actions import optional_cleanup
from cleanup_report import print_summary, send_notification


def main():
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", errors="replace")
    config = Path(__file__).resolve().parent.parent / "config/cleanup-config.json"
    if not config.exists():
        config = Path(__file__).with_name("cleanup-config.json")
    options = parse_options(config)
    if options.dry_run:
        print("预览模式：不会删除任何文件，也不会发送桌面通知。")
    start = time.monotonic()
    before = disk_space("清理前磁盘空间：")
    total, records = counters(), []

    def add(label, result):
        records.append((label, result))
        for key in total:
            total[key] += result[key]

    def apply_rules(rules):
        for label, root, child, days, *extra in rules:
            try:
                result = report_target(label, cache_target(root, child), days, options.dry_run, protect_access=extra[0] if extra else True, skip_permission_denied=True, allow_hardlinks=extra[1] if len(extra) > 1 else False)
                add(label, result)
            except PermissionError as error:
                access_error(total, error, Path(root).expanduser() / child, True)
            except (OSError, ValueError) as error:
                total["errors"] += 1
                print("缓存规则失败：", label, str(error).replace(str(Path.home()), "~"))

    for directory, days in [("tmp", options.workspace_tmp_days), ("logs", options.workspace_log_days)]:
        try:
            add("工作目录 " + directory, cleanup_files(directory, days, options.dry_run))
        except (OSError, ValueError) as error:
            total["errors"] += 1
            print("工作目录规则失败：", directory, str(error).replace(str(Path.home()), "~"))
    if options.user_caches:
        apply_rules(user_cache_rules(days=options.download_days, temp_days=options.workspace_tmp_days, extra_rules=options.extra_cache_rules))
    if options.agent_caches:
        apply_rules(agent_cache_rules(options.agent_days))
    tools = optional_cleanup(options, apply_rules)
    after = disk_space("清理后磁盘空间：")
    print_summary(total, records, tools, before, after, options.dry_run, time.monotonic() - start)
    failed = bool(total["errors"] or any(status == "执行失败" for _, status in tools))
    if options.notify and not options.dry_run:
        send_notification(total, tools, before, after, failed)
    return int(failed)


if __name__ == "__main__":
    sys.exit(main())

